INSERT INTO feature VALUES('sized-atoms','types','Width atoms and their literals','native-primitives','partial','ordinary',NULL,'The integer widths `u8`, `u16`, `u32`, `u64`, `usize`, `i8`, `i16`, `i32`, `i64` and `isize` are base atoms of their own, apart from `Integer` and from one another, and a literal states its width with a suffix, `7u32`, its digits range-checked at the literal; `usize` and `isize` hold 64 bits, the word of each target; a width converts to `Integer` exactly, `u64.to_integer`, and an integer to a width by its remainder modulo two to the width''s bit count, `u64.from_integer`, as Rust''s `as` cast does; `f64` is its own atom (`floating-point`) and `f32` is not yet in.','kernel-term kernel-core core-term core-checker surface-lowering surface-pretty runtime-emitter','corpus/model/basics/widths.gandr corpus/model/basics/machine-widths.gandr corpus/model/basics/arithmetic.gandr corpus/pathological/basics/kernel-admission-boundary.gandr','corpus/ledger/features/sized-atoms.gandr','#1109 #2563');
